import itertools, time, sys

# --- check arity-4 polymorphisms of the 1-in-3 relation, and whether any fails to preserve OR
R=[(1,0,0),(0,1,0),(0,0,1)]
ORset=set(itertools.product([0,1],repeat=3))-{(0,0,0)}
def preserves4(table):
    for a in R:
        for b in R:
            for c in R:
                for d in R:
                    idx=[(a[i]<<3)|(b[i]<<2)|(c[i]<<1)|d[i] for i in range(3)]
                    if tuple(table[idx[i]] for i in range(3)) not in R: return False
    return True
def preserves_rel4(table,rel):
    for a in rel:
        for b in rel:
            for c in rel:
                for d in rel:
                    idx=[(a[i]<<3)|(b[i]<<2)|(c[i]<<1)|d[i] for i in range(3)]
                    if tuple(table[idx[i]] for i in range(3)) not in rel: return False
    return True
cnt=0; bad=0
for table in itertools.product([0,1],repeat=16):
    if preserves4(table):
        cnt+=1
        if not preserves_rel4(table,ORset): bad+=1
print("arity4 polymorphisms:",cnt,"not preserving OR:",bad, flush=True)

# --- memoized DFS for OR gadget
def find_gadget(k, maxs, timelimit=100):
    n=3+k
    assignments=list(itertools.product([0,1],repeat=n))
    N=len(assignments)
    full=(1<<N)-1
    triples=list(itertools.combinations(range(n),3))
    cmask=[]
    for t in triples:
        m=0
        for i,a in enumerate(assignments):
            if a[t[0]]+a[t[1]]+a[t[2]]==1: m|=1<<i
        cmask.append(m)
    pat_mask={}
    for p in itertools.product([0,1],repeat=3):
        m=0
        for i,a in enumerate(assignments):
            if (a[0],a[1],a[2])==p: m|=1<<i
        pat_mask[p]=m
    nonzero=[p for p in pat_mask if p!=(0,0,0)]
    def proj_ok(S):
        for p in nonzero:
            if S & pat_mask[p]==0: return False
        if S & pat_mask[(0,0,0)]!=0: return False
        return True
    def proj_possible(S):
        for p in nonzero:
            if S & pat_mask[p]==0: return False
        return True
    start=time.time(); result=[None]; failed=set()
    def dfs(S, si, depth, chosen):
        if result[0] is not None: return True
        if time.time()-start>timelimit: return False
        if proj_ok(S):
            result[0]=list(chosen); return True
        if depth==maxs: return False
